class Book:
    def __init__(self, title, author):
        self.title = title
        self.author = author
        self.borrowed = False

    def __repr__(self):
        return f"{self.title} by {self.author}"

class Library:
    def __init__(self):
        self.books = []

    def add(self, book):
        self.books.append(book)

    def borrow(self, title):
        for book in self.books:
            if book.title == title and not book.borrowed:
                book.borrowed = True
                return book
        return None

    def available(self):
        return [b for b in self.books if not b.borrowed]

lib = Library()
lib.add(Book("Python 101", "Rao"))
lib.add(Book("Crab Tales", "Xecxec"))
print(lib.borrow("Python 101"))
print(lib.borrow("Python 101"))
print(lib.available())

class Book:
    def __init__(self, title):
        self.title = title
        self.borrowed = False

class Member:
    def __init__(self, name):
        self.name = name
        self.loans = []

    def borrow(self, book):
        if book.borrowed:
            return False
        book.borrowed = True
        self.loans.append(book.title)
        return True

b = Book("Python 101")
m1 = Member("Asha")
m2 = Member("Ravi")
print(m1.borrow(b))
print(m2.borrow(b))
print(m1.loans, m2.loans)

